const queue = [];
const history = [];
function dispatch(cmd) { queue.push(cmd); queueMicrotask(drain); }
function drain() {
  while (queue.length) {
    const cmd = queue.shift();
    const inverse = cmd.execute();          // command may return its own undo
    if (inverse) history.push(inverse);
  }
}
